package server_test

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/ai-verification/http-server/server"
)

func setup() *httptest.Server {
	store := server.NewStore()
	h := server.NewHandler(store)
	return httptest.NewServer(h)
}

func TestListEmpty(t *testing.T) {
	s := setup()
	defer s.Close()
	resp, _ := http.Get(s.URL + "/items")
	if resp.StatusCode != 200 {
		t.Fatalf("expected 200, got %d", resp.StatusCode)
	}
	var items []server.Item
	json.NewDecoder(resp.Body).Decode(&items)
	if len(items) != 0 {
		t.Fatalf("expected empty, got %v", items)
	}
}

func TestCreate(t *testing.T) {
	s := setup()
	defer s.Close()
	body := bytes.NewBufferString(`{"name":"widget"}`)
	resp, _ := http.Post(s.URL+"/items", "application/json", body)
	if resp.StatusCode != 201 {
		t.Fatalf("expected 201, got %d", resp.StatusCode)
	}
	var item server.Item
	json.NewDecoder(resp.Body).Decode(&item)
	if item.Name != "widget" || item.ID == 0 {
		t.Fatalf("unexpected item: %+v", item)
	}
}

func TestListAfterCreate(t *testing.T) {
	s := setup()
	defer s.Close()
	http.Post(s.URL+"/items", "application/json", bytes.NewBufferString(`{"name":"a"}`))
	http.Post(s.URL+"/items", "application/json", bytes.NewBufferString(`{"name":"b"}`))
	resp, _ := http.Get(s.URL + "/items")
	var items []server.Item
	json.NewDecoder(resp.Body).Decode(&items)
	if len(items) != 2 {
		t.Fatalf("expected 2 items, got %d", len(items))
	}
}

func TestDelete(t *testing.T) {
	s := setup()
	defer s.Close()
	resp, _ := http.Post(s.URL+"/items", "application/json", bytes.NewBufferString(`{"name":"x"}`))
	var item server.Item
	json.NewDecoder(resp.Body).Decode(&item)
	req, _ := http.NewRequest(http.MethodDelete, s.URL+"/items/"+itoa(item.ID), nil)
	http.DefaultClient.Do(req)
	resp2, _ := http.Get(s.URL + "/items")
	var items []server.Item
	json.NewDecoder(resp2.Body).Decode(&items)
	if len(items) != 0 {
		t.Fatalf("expected 0 items after delete, got %d", len(items))
	}
}

func TestDeleteNotFound(t *testing.T) {
	s := setup()
	defer s.Close()
	req, _ := http.NewRequest(http.MethodDelete, s.URL+"/items/999", nil)
	resp, _ := http.DefaultClient.Do(req)
	if resp.StatusCode != 404 {
		t.Fatalf("expected 404, got %d", resp.StatusCode)
	}
}

func itoa(n int) string {
	return strconv.Itoa(n)
}
